import{_ as o,C as t,o as i,c as s,E as a,a2 as c}from"./chunks/framework.uPk2SrVb.js";const v=JSON.parse('{"title":"An Approval Can Be Spent Before an Effect Is Delivered","description":"","frontmatter":{"title":"An Approval Can Be Spent Before an Effect Is Delivered","date":"2026-10-31","column":"industry-architecture","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"单次审批已消费，能否说明外部效果已交付？（Can evidence that a single-use approval was consumed establish completion of its external effect?）","summary":"Source-derived isolated database probes admitted one consumer per race. Intentionally omitting the subsequent effect left retry refused, separating consumption evidence from external delivery and crash recovery.","sources":["https://arxiv.org/html/2610.21063v1","https://github.com/Sports-Vision-Inc/agent-step-up/tree/056742b00a9d116a57525c75704820bb87756e84","https://raw.githubusercontent.com/microsoft/agent-governance-toolkit/main/docs/adr/0030-action-bound-approval-protocol.md"],"pageClass":"runtime-v6-article","item_id":"SIG-20261031-001","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-31-sig-20261031-001-final-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-10-31-sig-20261031-001.md","filePath":"en/industry/2026-10-31-sig-20261031-001.md","lastUpdated":null}'),d={name:"en/industry/2026-10-31-sig-20261031-001.md"};function l(p,e,u,h,m,f){const r=t("ArticleCover"),n=t("ArticleTableScroll");return i(),s("div",null,[a(r,{image:"/assets/covers/daily-2026-10-31-sig-20261031-001-final-cover.png",kicker:"Research",title:"An Approval Can Be Spent Before an Effect Is Delivered",summary:"Source-derived isolated database probes admitted one consumer per race. Intentionally omitting the subsequent effect left retry refused, separating consumption evidence from external delivery and crash recovery.",version:"2026-10-31",languageHref:"/zh/industry/2026-10-31-sig-20261031-001",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=c('<h1 id="an-approval-can-be-spent-before-an-effect-is-delivered" tabindex="-1">An Approval Can Be Spent Before an Effect Is Delivered <a class="header-anchor" href="#an-approval-can-be-spent-before-an-effect-is-delivered" aria-label="Permalink to &quot;An Approval Can Be Spent Before an Effect Is Delivered&quot;">​</a></h1><h2 id="what-does-a-refused-retry-actually-establish" tabindex="-1">What does a refused retry actually establish? <a class="header-anchor" href="#what-does-a-refused-retry-actually-establish" aria-label="Permalink to &quot;What does a refused retry actually establish?&quot;">​</a></h2><p>Single-use approval consumption can restrict reuse without answering whether an external action finished. In the current internal experiment, every concurrent race admitted exactly one consumer. In a separate controlled case, the probe deliberately omitted the effect after committing consumption; a later retry was still refused. Local token state and external delivery are different facts.</p><p>The subject is the database consumption mechanism at a pinned ASU revision. The bounded conclusion is that approval consumption and effect delivery require separate evidence. We did not cause a real gateway crash or establish that a deployed system lost a user action. <a href="https://github.com/Sports-Vision-Inc/agent-step-up/tree/056742b00a9d116a57525c75704820bb87756e84" target="_blank" rel="noreferrer">Inspected source revision</a></p><h2 id="what-the-isolated-probe-measured" tabindex="-1">What the isolated probe measured <a class="header-anchor" href="#what-the-isolated-probe-measured" aria-label="Permalink to &quot;What the isolated probe measured&quot;">​</a></h2><p>This was a source-derived isolated function probe: the pinned consumption and transaction methods were extracted and executed against SQLite. The audit sink was replaced with an in-memory recorder and the clock was injected. Results consequently do not cover failures in the original audit system or real clock skew.</p><p>Twenty races each used 16 independent database connections: 320 concurrent calls in total. Exactly one consumer succeeded in each race, giving 20 successes and 300 refusals. These are internal measurements under the tested thread-and-connection conditions, not multiprocess stress results or a universal concurrency proof.</p><table tabindex="0"><thead><tr><th>Control condition</th><th>Consumption outcome</th></tr></thead><tbody><tr><td>Approved, current time before expiry</td><td>Accepted</td></tr><tr><td>Current time exactly at expiry</td><td>Refused</td></tr><tr><td>Expired</td><td>Refused</td></tr><tr><td>Pending</td><td>Refused</td></tr><tr><td>Denied</td><td>Refused</td></tr><tr><td>Missing record</td><td>Refused</td></tr></tbody></table><p>Source: the current internal source-derived probe dated 2026-10-31, using methods from the <a href="https://github.com/Sports-Vision-Inc/agent-step-up/blob/056742b00a9d116a57525c75704820bb87756e84/asu/store.py" target="_blank" rel="noreferrer">pinned database implementation</a>. All six controls matched expectations. No full gateway, signature verification or real external resource was exercised.</p><p>The controlled interruption must also be named precisely: first consumption succeeded, its transaction committed, the harness intentionally omitted the external effect, and a second consumption was refused. The absent effect was constructed by the test; it was not observed in a real incident. This shows that the consumption method itself supplies no external-delivery evidence, not that the full product lacks every possible recovery mechanism.</p><h2 id="the-boundary-between-consuming-and-executing" tabindex="-1">The boundary between consuming and executing <a class="header-anchor" href="#the-boundary-between-consuming-and-executing" aria-label="Permalink to &quot;The boundary between consuming and executing&quot;">​</a></h2><p>Static inspection shows a conditional update inside an immediate write transaction: only an approved, unexpired row can become consumed. The gateway checks session, user, stored and resubmitted descriptor digests, re-resolves raw arguments and may reverify receipts. It consumes approval before entering the actual effect-execution path. <a href="https://github.com/Sports-Vision-Inc/agent-step-up/blob/056742b00a9d116a57525c75704820bb87756e84/asu/gateway.py" target="_blank" rel="noreferrer">Gateway implementation</a></p><p>The database transaction protects competing updates to that approval record. It does not automatically include durable external effects within the same local transaction. Conflating these layers promotes at-most-once consumption into exactly-once delivery. Static ordering and the isolated probe support separating the boundaries; they provide no measured probability of loss after real crashes.</p><p>Microsoft’s agent-governance-toolkit ADR 0030 binds approval to an action digest and policy/chain versions, requires execution-time revalidation, and places consumption at the transaction or idempotency boundary that begins execution. An individual allow vote is not an execution token. This design requirement helps frame the boundary but does not establish compliance by every integration or rank two systems under matched security tests. <a href="https://raw.githubusercontent.com/microsoft/agent-governance-toolkit/main/docs/adr/0030-action-bound-approval-protocol.md" target="_blank" rel="noreferrer">Action-bound approval protocol</a></p><h2 id="recovery-needs-additional-effect-evidence" tabindex="-1">Recovery needs additional effect evidence <a class="header-anchor" href="#recovery-needs-additional-effect-evidence" aria-label="Permalink to &quot;Recovery needs additional effect evidence&quot;">​</a></h2><p>An externally effective execution system could retain approval resolution, committed consumption, attempted effect and effect receipt separately. This is our architectural interpretation of the experiment, not a validated recovery implementation. An interruption after consumption but before a receipt requires resource-specific evidence for confirming the outcome or a defined compensation boundary.</p><p>A consumed flag alone cannot establish delivery. Nor should automatic replay be recommended without verifying the resource’s idempotency boundary. A resource may offer durable idempotency keys, queries or reconciliation that fill gaps outside this probe. Their omission here is not evidence of their universal absence.</p><p>Consume-before-effect also has a clear purpose: preventing repeated use of an approval. Our result does not establish that the ordering is wrong or that reversing it is generally safer. A particular integration needs to explain both anti-replay and recoverable delivery rather than substitute success at one objective for evidence about the other.</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>Internal experimental evidence comes from the current isolated function probe, not an independent third-party test. Static source observation describes a pinned implementation; a public design document supplies requirements; paper attack results remain author reports. These roles are distinct.</p><p>Implementation material is the maintainers’ <a href="https://github.com/Sports-Vision-Inc/agent-step-up/tree/056742b00a9d116a57525c75704820bb87756e84" target="_blank" rel="noreferrer">pinned source</a>, revision <code>056742b00a9d116a57525c75704820bb87756e84</code>. The comparison document is Microsoft’s <a href="https://raw.githubusercontent.com/microsoft/agent-governance-toolkit/main/docs/adr/0030-action-bound-approval-protocol.md" target="_blank" rel="noreferrer">ADR 0030</a>. The paper is the authors’ <a href="https://arxiv.org/html/2610.21063v1" target="_blank" rel="noreferrer">preprint, version 1</a>; our probe date is 2026-10-31. Paper experiment revisions differ from the inspected commit, and two experiments disclose dirty working trees. They cannot be treated as identical executed versions.</p><p>The authors report forged-narration attack success falling from 0.54 to 0.03 across 609 task pairs under an exact-compare oracle. We did not reproduce that result. There are no human-subject data; the oracle is an upper-bound condition, and host confirmation matches the system under measured conditions except grant-related differences. This does not establish that a second device improves real human decisions. <a href="https://arxiv.org/html/2610.21063v1" target="_blank" rel="noreferrer">Paper sections 7–8</a></p><p>Formal materials explicitly assume trusted-field decisions, closed enrollment and an honest rendering origin, and distinguish key signatures from evidence of human consent. Parts of the model exclude expiry, session binding, amount aggregation, free-text grants and flood control. Historical vulnerability comments in red-team tests are not current failing-test results. <a href="https://github.com/Sports-Vision-Inc/agent-step-up/blob/056742b00a9d116a57525c75704820bb87756e84/formal/README.md" target="_blank" rel="noreferrer">Formal materials</a> We ran neither those proofs nor attack tests. Publication, citation and successful implementation do not automatically establish general validity.</p><p>The cover is editorial artwork based on the consumption/delivery boundary. Its empty result location represents missing evidence, not inevitable effect loss in the real system.</p><h2 id="the-delivery-responsibility-still-untested" tabindex="-1">The delivery responsibility still untested <a class="header-anchor" href="#the-delivery-responsibility-still-untested" aria-label="Permalink to &quot;The delivery responsibility still untested&quot;">​</a></h2><p>We did not test real gateway crashes, audit rollback, database corruption, multiprocess scheduling or external resource idempotency. Signatures, trusted rendering and cross-language canonicalization require separate validation. Paper cells that are static or derived, placeholder stimuli and unaudited proprietary systems also limit cross-system extrapolation.</p><p>The unresolved question is concrete: when approval is consumed but the effect receipt is missing, what recoverable resource evidence can this integration produce? Until that evidence is available, consumption success can be reported accurately while delivery remains a separate fact to determine.</p>',27))])}const y=o(d,[["render",l]]);export{v as __pageData,y as default};
